var e={preflight:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Một lần kiểm tra nhanh chỉ-đọc xem máy in đã sẵn sàng để bắt đầu in chưa.`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Kiểm tra lại`}},checking:{t:0,b:{t:2,i:[{t:3}],s:`Đang kiểm tra...`}},ready:{t:0,b:{t:2,i:[{t:3}],s:`Sẵn sàng để in`}},notReady:{t:0,b:{t:2,i:[{t:3}],s:`Chưa sẵn sàng để in`}},checks:{unreachable:{fail:{t:0,b:{t:2,i:[{t:3}],s:`Không thể kết nối tới máy in`}}},klippy:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Klipper đã sẵn sàng`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Klipper chưa sẵn sàng (trạng thái: `},{t:4,k:`state`},{t:3,v:`)`}]}}},idle:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Không có lần in nào đang chạy`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Một lần in đã đang chạy (`},{t:4,k:`state`},{t:3,v:`)`}]}}},homed:{pass:{t:0,b:{t:2,i:[{t:3}],s:`Tất cả các trục đã về gốc`}},fail:{t:0,b:{t:2,i:[{t:3,v:`Các trục chưa về gốc (`},{t:4,k:`axes`},{t:3,v:`); việc bắt đầu in thường về gốc trước`}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Hướng dẫn`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Hướng dẫn kiểm tra trước khi in`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Đóng`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`Kiểm tra trước khi in là gì?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Một cái nhìn chỉ-đọc xem máy in đã sẵn sàng để bắt đầu chưa: nó không bao giờ di chuyển hay thay đổi bất cứ thứ gì, chỉ báo cáo. Các yếu tố chặn cứng làm kết luận chuyển sang đỏ; cảnh báo chỉ để thông tin nhưng không chặn.`}}},checks:{title:{t:0,b:{t:2,i:[{t:3}],s:`Những gì được kiểm tra`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Klipper đã sẵn sàng (không bị tắt hoặc lỗi), không có lần in nào đang chạy, và liệu các trục đã về gốc chưa (chỉ để tham khảo, vì việc bắt đầu in thường về gốc trước).`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Thuật ngữ`}}}},glossary:{klippyState:{term:{t:0,b:{t:2,i:[{t:3}],s:`Trạng thái Klipper`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Trạng thái riêng của Klipper - 'ready' (sẵn sàng) nghĩa là đã kết nối và rảnh; 'shutdown' (đã tắt) hoặc 'error' (lỗi) nghĩa là không thể in cho đến khi được xử lý.`}}},homing:{term:{t:0,b:{t:2,i:[{t:3}],s:`Về gốc (Homing)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Di chuyển từng trục đến công tắc giới hạn (endstop) để máy in biết đầu in đang ở đâu. Hầu hết các quy trình bắt đầu in đều tự động về gốc.`}}}}}}};export{e as default};